#!/usr/bin/env python3
'''Scoped standard-library check for K-SYS-006.

The reference gate is a declarative evidence-state model. The chapter gate is
a separate sequential state machine. The check enumerates finite evidence
profiles, compares both, checks monotonicity for favorable evidence, exercises
edge cases, and includes intentionally faulty negative controls. It also reads
the assigned chapter only to check the required provenance marker, unique
source heading, offline links and pseudocode fence. No project imports,
network, credentials, subprocesses or file writes are used.
'''

from itertools import product
from pathlib import Path

BOOL_KEYS = (
    'scope_declared',
    'identity_match',
    'terminal_complete',
    'same_condition',
    'observation',
    'independent',
    'mechanism',
    'heldout',
    'paired_budget_matched',
    'same_scope_conflict',
    'heldout_conflict',
)
CONTROLS = ('absent', 'rejected', 'accepted')
KINDS = ('MECH', 'OBS', 'TRANSFER', 'BUILD_EFFECT')
FAVORABLE_KEYS = (
    'scope_declared',
    'identity_match',
    'terminal_complete',
    'same_condition',
    'observation',
    'independent',
    'mechanism',
    'heldout',
    'paired_budget_matched',
)
RANK = {
    'BLOCKED': 0,
    'SOURCE_SUPPORTED': 1,
    'OBSERVED': 2,
    'CHECKED': 3,
    'SUPPORTED': 4,
    'TRANSFERABLE': 5,
    'SUPPORTED_EFFECT': 5,
    'CONTESTED': -1,
}

def flags(**kw):
    d = {key: False for key in BOOL_KEYS}
    d['control'] = 'absent'
    d.update(kw)
    return d

def reference_gate(kind, f):
    if not f['scope_declared'] or not f['identity_match']:
        return 'BLOCKED'
    if f['control'] == 'accepted':
        return 'BLOCKED'
    if f['same_scope_conflict']:
        return 'CONTESTED'
    if kind == 'MECH':
        if f['mechanism']:
            return 'SOURCE_SUPPORTED'
        return 'BLOCKED'
    if not f['terminal_complete']:
        return 'BLOCKED'
    if not f['observation'] or not f['same_condition']:
        return 'BLOCKED'
    checked = f['independent'] and f['control'] == 'rejected'
    if not checked:
        return 'OBSERVED'
    if kind == 'OBS':
        if f['mechanism']:
            return 'SUPPORTED'
        return 'CHECKED'
    if kind == 'TRANSFER':
        if f['heldout'] and f['heldout_conflict']:
            return 'CONTESTED'
        if f['heldout'] and f['mechanism']:
            return 'TRANSFERABLE'
        return 'CHECKED'
    if kind == 'BUILD_EFFECT':
        if f['paired_budget_matched'] and f['heldout'] and f['mechanism']:
            return 'SUPPORTED_EFFECT'
        return 'CHECKED'
    return 'BLOCKED'

def chapter_gate(kind, f):
    if not (f['scope_declared'] and f['identity_match']):
        return 'BLOCKED'
    if f['control'] == 'accepted':
        return 'BLOCKED'
    if f['same_scope_conflict']:
        return 'CONTESTED'
    if kind == 'MECH':
        return 'SOURCE_SUPPORTED' if f['mechanism'] else 'BLOCKED'
    common = f['terminal_complete'] and f['observation'] and f['same_condition']
    if not common:
        return 'BLOCKED'
    reference_ok = f['independent'] and f['control'] == 'rejected'
    if not reference_ok:
        return 'OBSERVED'
    if kind == 'OBS':
        return 'SUPPORTED' if f['mechanism'] else 'CHECKED'
    if kind == 'TRANSFER':
        if f['heldout'] and f['heldout_conflict']:
            return 'CONTESTED'
        if f['heldout'] and f['mechanism']:
            return 'TRANSFERABLE'
        return 'CHECKED'
    if kind == 'BUILD_EFFECT':
        if f['paired_budget_matched'] and f['heldout'] and f['mechanism']:
            return 'SUPPORTED_EFFECT'
        return 'CHECKED'
    return 'BLOCKED'

def naive_gate(kind, f):
    if f['scope_declared'] and f['identity_match'] and f['observation']:
        return 'SUPPORTED'
    return 'BLOCKED'

def all_profiles():
    for bits in product((False, True), repeat=len(BOOL_KEYS)):
        f = dict(zip(BOOL_KEYS, bits))
        for control in CONTROLS:
            f['control'] = control
            yield dict(f)

def count_mismatches():
    mismatches = []
    total = 0
    for kind in KINDS:
        for f in all_profiles():
            total += 1
            expected = reference_gate(kind, f)
            actual = chapter_gate(kind, f)
            if expected != actual:
                mismatches.append((kind, dict(f), expected, actual))
    return total, mismatches

def check_monotonicity():
    violations = []
    for kind in KINDS:
        for f in all_profiles():
            if f['control'] == 'accepted':
                continue
            if f['same_scope_conflict'] or f['heldout_conflict']:
                continue
            old = chapter_gate(kind, f)
            for key in FAVORABLE_KEYS:
                if f[key]:
                    continue
                upgraded = dict(f)
                upgraded[key] = True
                new = chapter_gate(kind, upgraded)
                if RANK[new] < RANK[old]:
                    violations.append((kind, key, old, new))
            if f['control'] == 'absent':
                upgraded = dict(f)
                upgraded['control'] = 'rejected'
                new = chapter_gate(kind, upgraded)
                if RANK[new] < RANK[old]:
                    violations.append((kind, 'control', old, new))
    return violations

def strict_identity(expected, observed):
    if set(expected) != set(observed):
        return False
    return all(observed[key] == expected[key] for key in expected)

def permissive_identity(expected, observed):
    allowed = set(expected.values())
    return all(value in allowed for value in observed.values())

def effective_independent(records, dimension, producer_error_model):
    for record_dimension, error_model in records:
        if record_dimension == dimension and error_model != producer_error_model:
            return True
    return False

def structural_errors(text):
    errors = []
    lines = text.splitlines()
    marker = '<!-- infraagents:provenance -->'
    if text.count(marker) != 1:
        errors.append('provenance_marker_count')
    level2 = [line[3:].strip() for line in lines if line.startswith('## ')]
    if level2.count('来源与推导') != 1:
        errors.append('source_heading_count')
    if len(level2) != len(set(level2)):
        errors.append('duplicate_level2_heading')
    lowered = text.lower()
    if 'http://' in lowered or 'https://' in lowered:
        errors.append('http_url_present')
    fences = [line.strip() for line in lines if line.strip().startswith('```')]
    if fences != ['```pseudocode', '```']:
        errors.append('code_fence_not_exactly_pseudocode')
    return errors

def find_chapter():
    here = Path(__file__).resolve()
    candidates = [
        Path.cwd() / 'knowledge/system-semantics/evidence-and-independent-checks.md',
        here.parent.parent / 'knowledge/system-semantics/evidence-and-independent-checks.md',
        here.parent / '../knowledge/system-semantics/evidence-and-independent-checks.md',
    ]
    for path in candidates:
        if path.exists():
            return path
    return None

def main():
    total, mismatches = count_mismatches()
    violations = check_monotonicity()

    edge_cases = [
        ('mech_source', 'MECH', flags(scope_declared=True, identity_match=True, mechanism=True), 'SOURCE_SUPPORTED'),
        ('obs_needs_independent', 'OBS', flags(scope_declared=True, identity_match=True, terminal_complete=True, same_condition=True, observation=True, mechanism=True), 'OBSERVED'),
        ('transfer_needs_heldout', 'TRANSFER', flags(scope_declared=True, identity_match=True, terminal_complete=True, same_condition=True, observation=True, independent=True, control='rejected', mechanism=True, heldout=False), 'CHECKED'),
        ('build_effect_needs_pairing', 'BUILD_EFFECT', flags(scope_declared=True, identity_match=True, terminal_complete=True, same_condition=True, observation=True, independent=True, control='rejected', mechanism=True, heldout=True, paired_budget_matched=False), 'CHECKED'),
        ('missing_terminal_blocks', 'OBS', flags(scope_declared=True, identity_match=True, terminal_complete=False, same_condition=True, observation=True, independent=True, control='rejected', mechanism=True), 'BLOCKED'),
        ('accepted_bad_control_blocks', 'OBS', flags(scope_declared=True, identity_match=True, terminal_complete=True, same_condition=True, observation=True, independent=True, control='accepted', mechanism=True), 'BLOCKED'),
        ('same_scope_conflict_contests', 'OBS', flags(scope_declared=True, identity_match=True, terminal_complete=True, same_condition=True, observation=True, independent=True, control='rejected', mechanism=True, same_scope_conflict=True), 'CONTESTED'),
        ('transfer_heldout_conflict_contests', 'TRANSFER', flags(scope_declared=True, identity_match=True, terminal_complete=True, same_condition=True, observation=True, independent=True, control='rejected', mechanism=True, heldout=True, heldout_conflict=True), 'CONTESTED'),
    ]
    edge_failures = []
    for name, kind, f, expected in edge_cases:
        actual = reference_gate(kind, f)
        if actual != expected:
            edge_failures.append((name, expected, actual))

    no_independent = flags(scope_declared=True, identity_match=True, terminal_complete=True, same_condition=True, observation=True, mechanism=True)
    negative_detected = reference_gate('OBS', no_independent) == 'OBSERVED' and naive_gate('OBS', no_independent) == 'SUPPORTED'

    missing_terminal = flags(scope_declared=True, identity_match=True, terminal_complete=False, same_condition=True, observation=True, independent=True, control='rejected', mechanism=True)
    terminal_detected = reference_gate('OBS', missing_terminal) == 'BLOCKED' and naive_gate('OBS', missing_terminal) == 'SUPPORTED'

    accepted_bad = flags(scope_declared=True, identity_match=True, terminal_complete=True, same_condition=True, observation=True, independent=True, control='accepted', mechanism=True)
    bad_control_detected = reference_gate('OBS', accepted_bad) == 'BLOCKED' and naive_gate('OBS', accepted_bad) == 'SUPPORTED'

    conflict_flags = flags(scope_declared=True, identity_match=True, terminal_complete=True, same_condition=True, observation=True, independent=True, control='rejected', mechanism=True, same_scope_conflict=True)
    conflict_detected = reference_gate('OBS', conflict_flags) == 'CONTESTED' and naive_gate('OBS', conflict_flags) == 'SUPPORTED'

    expected_ids = {'A': 17, 'B': 99}
    duplicate_values = {'A': 17, 'B': 17}
    empty_values = {}
    identity_detected = (not strict_identity(expected_ids, duplicate_values)) and permissive_identity(expected_ids, duplicate_values)
    empty_detected = (not strict_identity(expected_ids, empty_values)) and permissive_identity(expected_ids, empty_values)

    dependent_records = [('page_index', 'page_walk'), ('page_index', 'page_walk')]
    independent_records = [('page_index', 'page_walk'), ('page_index', 'logical_rebuild')]
    shared_model = effective_independent(dependent_records, 'page_index', 'page_walk')
    separate_model = effective_independent(independent_records, 'page_index', 'page_walk')
    independence_detected = (not shared_model) and separate_model

    chapter_path = find_chapter()
    chapter_found = chapter_path is not None
    if chapter_found:
        text = chapter_path.read_text(encoding='utf-8')
        structural = structural_errors(text)
    else:
        structural = ['chapter_not_found']

    bad_lines = [
        '# bad',
        '',
        '## 来源与推导',
        '',
        '## 来源与推导',
        '',
        '```python',
        'x = 1',
        '```',
    ]
    bad_text = chr(10).join(bad_lines)
    bad_errors = structural_errors(bad_text)
    structural_negative_detected = bool(bad_errors)

    print('SCOPED K-SYS-006 CHECK')
    print('profiles_checked={0}'.format(total))
    print('reference_vs_chapter_mismatches={0}'.format(len(mismatches)))
    print('favorable_monotonicity_violations={0}'.format(len(violations)))
    print('edge_case_failures={0}'.format(len(edge_failures)))
    print('negative_control_detected={0}'.format(negative_detected))
    print('terminal_outcome_negative_control_detected={0}'.format(terminal_detected))
    print('accepted_bad_control_detected={0}'.format(bad_control_detected))
    print('same_scope_conflict_detected={0}'.format(conflict_detected))
    print('identity_duplicate_negative_control_detected={0}'.format(identity_detected))
    print('empty_identity_negative_control_detected={0}'.format(empty_detected))
    print('duplicate_independence_detected={0}'.format(independence_detected))
    print('chapter_found={0}'.format(chapter_found))
    print('structural_errors={0}'.format(structural))
    print('structural_negative_control_detected={0}'.format(structural_negative_detected))

    if mismatches:
        for item in mismatches[:3]:
            print('mismatch_sample={0}'.format(item))
    if violations:
        for item in violations[:3]:
            print('monotonicity_sample={0}'.format(item))
    if edge_failures:
        for item in edge_failures:
            print('edge_failure={0}'.format(item))

    ok = (
        total > 0
        and not mismatches
        and not violations
        and not edge_failures
        and negative_detected
        and terminal_detected
        and bad_control_detected
        and conflict_detected
        and identity_detected
        and empty_detected
        and independence_detected
        and chapter_found
        and not structural
        and structural_negative_detected
    )
    if ok:
        print('PASS scoped: promotion gate matched exhaustive reference; negative controls and structural invariants were checked')
    else:
        print('FAIL scoped: see observations above')

if __name__ == '__main__':
    main()
